VALUES
  ('w1', 'Allot', 'allot', 1, 'verb', '/əˈlɒt/', '/əˈlɒt/', 'To allot means to perform or exhibit allot in a given academic or social context.', 'Biror narsani biror kishiga taqsimlab bermoq', 'Ajratmoq, bermoq', 'Allot (русский перевод)', 'The coach allotted each team five minutes to prepare a strategy.', 'Murabbiy har bir jamoaga strategiya tayyorlash uchun besh daqiqa ajratdi.', 'The coach ______ted each team five minutes to prepare a strategy.', 'allot', '"allocate","assign","distribute"'::TEXT[], '"allot time","allot resources"'::TEXT[], 'B2', 1, TRUE),
  ('w2', 'Appall', 'appall', 1, 'verb', '/əˈpɔːl/', '/əˈpɔːl/', 'To appall means to horrify, shock, or disgust someone.', 'Kimnidir qattiq qo''rqitmoq yoki hayratda qoldirmoq', 'Dahshatga solmoq, lol qoldirmoq', 'Appall (русский перевод)', 'The boy was appalled when he saw the accident.', 'Halokatni ko''rgan bola qattiq dahshatga tushdi.', 'The boy was ______ed when he saw the accident.', 'appall', '"horrify","shock","dismay"'::TEXT[], '"deeply appalled","appall the public"'::TEXT[], 'B2', 2, TRUE),
  ('w3', 'Cache', 'cache', 1, 'noun', '/kæʃ/', '/kæʃ/', 'To cache means to perform or exhibit cache in a given academic or social context.', 'Qimmatbaho narsalarni saqlash uchun yashirin joy', 'Maxfiy ombor, yashirin joy', 'Cache (русский перевод)', 'The pirates kept their jewelry in a cache hidden in a cave.', 'Qaroqchilar o''z taqinchoqlarini g''orda yashirilgan maxfiy omborda saqlashgan.', 'The pirates kept their jewelry in a ______ hidden in a cave.', 'cache', '"hoard","hiding place","stash"'::TEXT[], '"cache of weapons","secret cache"'::TEXT[], 'B2', 3, TRUE),
  ('w4', 'Convenience', 'convenience', 1, 'noun', '/kənˈviː.ni.əns/', '/kənˈviː.ni.əns/', 'To convenience means to perform or exhibit convenience in a given academic or social context.', 'Ishni kam kuch bilan oson bajarish holati', 'Qulaylik', 'Convenience (русский перевод)', 'The Internet allows consumers to shop at their own convenience.', 'Internet iste''molchilarga o''zlariga qulay vaqtda xarid qilish imkonini beradi.', 'The Internet allows consumers to shop at their own ______.', 'convenience', '"comfort","handiness","ease"'::TEXT[], '"at your convenience","modern convenience"'::TEXT[], 'B2', 4, TRUE),
  ('w5', 'Dearth', 'dearth', 1, 'noun', '/dɜːθ/', '/dɜːθ/', 'To dearth means to perform or exhibit dearth in a given academic or social context.', 'Biror narsaning yetarli miqdorda bo''lmasligi', 'Yetishmovchilik, tanqislik', 'Dearth (русский перевод)', 'There is a dearth of money in my bank account. I can’t afford a new car.', 'Mening bank hisobimda pul tanqisligi bor.', 'There is a ______ of money in my bank account. I can’t afford a new car.', 'dearth', '"scarcity","shortage","lack"'::TEXT[], '"dearth of evidence","dearth of resources"'::TEXT[], 'B2', 5, TRUE),
  ('w6', 'Deliberate', 'deliberate', 1, 'adjective', '/dɪˈlɪb.ər.ət/', '/dɪˈlɪb.ər.ət/', 'If a thing you do is deliberate, you intend to do it.', 'Oldindan maqsad qilib, ataylab bajarilgan', 'Qasddan qilingan, o''ylab qilingan', 'Deliberate (русский перевод)', 'She made a deliberate effort to save money each month.', 'U har oy pul tejashga ongli ravishda harakat qildi.', 'She made a ______ effort to save money each month.', 'deliberate', '"intentional","planned","premeditated"'::TEXT[], '"deliberate action","deliberate attempt"'::TEXT[], 'B2', 6, TRUE),
  ('w7', 'Dire', 'dire', 1, 'adjective', '/daɪər/', '/daɪər/', 'When something is dire, it is terrible and very serious.', 'O''ta xavfli, jiddiy va salbiy oqibatlarga ega', 'Dahshatli, o''ta og''ir', 'Dire (русский перевод)', 'The tornado created a dire situation for the small town.', 'Tornado kichik shaharcha uchun og''ir vaziyatni keltirib chiqardi.', 'The tornado created a ______ situation for the small town.', 'dire', '"terrible","dreadful","critical"'::TEXT[], '"dire need","dire consequences"'::TEXT[], 'B2', 7, TRUE),
  ('w8', 'Elapse', 'elapse', 1, 'verb', '/ɪˈlæps/', '/ɪˈlæps/', 'To elapse means to pass, as in seconds, minutes, or hours.', 'Vaqt, daqiqalar yoki soatlarning o''tishi', 'O''tmoq (vaqt haqida)', 'Elapse (русский перевод)', 'A few seconds must elapse before you can take another picture.', 'Boshqa rasm olishingizdan oldin bir necha soniya o''tishi kerak.', 'A few seconds must ______ before you can take another picture.', 'elapse', '"pass by","slip away","go by"'::TEXT[], '"time elapsed","hours elapsed"'::TEXT[], 'B2', 8, TRUE),
  ('w9', 'Empathy', 'empathy', 1, 'noun', '/ˈem.pə.θi/', '/ˈem.pə.θi/', 'Empathy is sharing or understanding another person’s feelings.', 'Boshqa insonning his-tuyg''ularini tushunish va unga sherik bo''lish', 'Hamdardlik, his-tuyg''uni tushunish', 'Empathy (русский перевод)', 'The caring nurse had empathy for her patients.', 'G''amxo''r hamshira o''z bemorlariga samimiy hamdardlik bildirdi.', 'The caring nurse had ______ for her patients.', 'empathy', '"compassion","understanding","sympathy"'::TEXT[], '"feel empathy","deep empathy"'::TEXT[], 'B2', 9, TRUE),
  ('w10', 'Fanciful', 'fanciful', 1, 'adjective', '/ˈfæn.sɪ.fəl/', '/ˈfæn.sɪ.fəl/', 'When something is fanciful, it is unusual or unrealistic.', 'G''ayrioddiy yoki haqiqatga to''g''ri kelmaydigan', 'Xayoliy, haqiqatdan uzoq', 'Fanciful (русский перевод)', 'The girl had fanciful ideas about doing well in school without studying.', 'Qiz o''qimasdan turib a''lochi bo''lish haqidagi xayoliy orzularga ega edi.', 'The girl had ______ ideas about doing well in school without studying.', 'fanciful', '"unrealistic","imaginary","whimsical"'::TEXT[], '"fanciful idea","fanciful notion"'::TEXT[], 'B2', 10, TRUE),
  ('w11', 'Gripe', 'gripe', 1, 'verb', '/ɡraɪp/', '/ɡraɪp/', 'To gripe means to perform or exhibit gripe in a given academic or social context.', 'Doimiy ravishda norozilik bildirib turish', 'Nolimoq, tinimsiz shikoyat qilmoq', 'Gripe (русский перевод)', 'The researcher used the word gripe to clarify the findings in the study.', 'Lourens uy yumushlarini bajarishi kerak bo''lganda doim nolirdi.', 'The researcher used the word ______ to clarify the findings in the study.', 'gripe', '"complain","grumble","whine"'::TEXT[], '"constant gripes","gripe about"'::TEXT[], 'B2', 11, TRUE),
  ('w12', 'Grueling', 'grueling', 1, 'adjective', '/ˈɡruː.ə.lɪŋ/', '/ˈɡruː.ə.lɪŋ/', 'When something is grueling, it is very hard to do.', 'Jismoniy yoki aqliy jihatdan juda og''ir va charchatuvchi', 'Mashaqqatli, holdan toydiruvchi', 'Grueling (русский перевод)', 'The climber faced the grueling task of reaching the top of the steep mountain.', 'Tog''chi tik cho''qqiga chiqishdek mashaqqatli vazifaga duch keldi.', 'The climber faced the ______ task of reaching the top of the steep mountain.', 'grueling', '"exhausting","strenuous","demanding"'::TEXT[], '"grueling schedule","grueling workout"'::TEXT[], 'B2', 12, TRUE),
  ('w13', 'Mundane', 'mundane', 1, 'adjective', '/mʌnˈdeɪn/', '/mʌnˈdeɪn/', 'When something is mundane, it is boring, common, or ordinary.', 'Juda oddiy, bir xil yoki kundalik odatiy', 'Oddiy, zerikarli, kundalik', 'Mundane (русский перевод)', 'The man had the mundane chore of raking thousands of leaves into piles.', 'Erkak minglab to''kilgan barglarni yig''ishdek zerikarli yumushga ega edi.', 'The man had the ______ chore of raking thousands of leaves into piles.', 'mundane', '"ordinary","routine","monotonous"'::TEXT[], '"mundane task","mundane matters"'::TEXT[], 'B2', 13, TRUE),
  ('w14', 'Opt', 'opt', 1, 'verb', '/ɒpt/', '/ɒpt/', 'To opt is to make a choice, especially when deciding in favor of something.', 'Biror narsaning foydasiga qaror qabul qilmoq', 'Tanlamoq, ma''qul ko''rmoq', 'Opt (русский перевод)', 'My brother likes chocolate ice cream, but I always opt for vanilla.', 'Akam shokoladli muzqaymoqni yoqtiradi, lekin men doim vanilni tanlayman.', 'My brother likes chocolate ice cream, but I always ______ for vanilla.', 'opt', '"choose","select","decide on"'::TEXT[], '"opt for","opt to do something"'::TEXT[], 'B2', 14, TRUE),
  ('w15', 'Outrage', 'outrage', 1, 'noun', '/ˈaʊt.reɪdʒ/', '/ˈaʊt.reɪdʒ/', 'To outrage means to perform or exhibit outrage in a given academic or social context.', 'Adolatsizlik yoki yomonlikka nisbatan juda kuchli g''azab', 'G''azab, qattiq nafrat', 'Outrage (русский перевод)', 'Tommy was feeling outrage when his parents said he couldn’t go to the dance.', 'Ota-onasi ziyofatga borishga ruxsat bermaganda Tommi qattiq g''azablandi.', 'Tommy was feeling ______ when his parents said he couldn’t go to the dance.', 'outrage', '"fury","indignation","anger"'::TEXT[], '"public outrage","spark outrage"'::TEXT[], 'B2', 15, TRUE),
  ('w16', 'Paltry', 'paltry', 1, 'adjective', '/ˈpɔːl.tri/', '/ˈpɔːl.tri/', 'When an amount of something is paltry, it is very small.', 'Miqdori yoki ahamiyati juda kichik bo''lgan', 'Juda kam, arzimas', 'Paltry (русский перевод)', 'The poor man had a paltry sum of money.', 'Kambag''al kishida juda ozgina arzimas pul bor edi.', 'The poor man had a ______ sum of money.', 'paltry', '"meager","trivial","insignificant"'::TEXT[], '"paltry sum","paltry amount"'::TEXT[], 'B2', 16, TRUE),
  ('w17', 'Rectify', 'rectify', 1, 'verb', '/ˈrek.tɪ.faɪ/', '/ˈrek.tɪ.faɪ/', 'To rectify means to perform or exhibit rectify in a given academic or social context.', 'Xato yoki noxush vaziyatni bartaraf etib to''g''rilamoq', 'Tuzatmoq, to''g''irlamoq', 'Rectify (русский перевод)', 'I quickly rectified the spelling mistakes that I had on my essay.', 'Inshomda yo''l qo''ygan imlo xatolarimni tezda to''g''irladim.', 'I quickly rectified the spelling mistakes that I had on my essay.', 'rectify', '"correct","amend","remedy"'::TEXT[], '"rectify mistakes","rectify the situation"'::TEXT[], 'B2', 17, TRUE),
  ('w18', 'Resourceful', 'resourceful', 1, 'adjective', '/rɪˈzɔː.sfəl/', '/rɪˈzɔː.sfəl/', 'When someone is resourceful, they are good at dealing with hard situations.', 'Qiyin vaziyatlardan oson yo''l topa oladigan', 'Topqir, uddaburon', 'Resourceful (русский перевод)', '+ After his boat sunk, Matt was resourceful enough to build a raft.', 'Qayig''i cho''kib ketgach, Mett sol yasashga yetarlicha topqirlik ko''rsatdi.', '+ After his boat sunk, Matt was ______ enough to build a raft.', 'resourceful', '"clever","inventive","capable"'::TEXT[], '"resourceful person","resourceful mind"'::TEXT[], 'B2', 18, TRUE),
  ('w19', 'Sustenance', 'sustenance', 1, 'noun', '/ˈsʌs.tɪ.nəns/', '/ˈsʌs.tɪ.nəns/', 'To sustenance means to perform or exhibit sustenance in a given academic or social context.', 'Tirik qolish uchun zarur bo''lgan oziq-ovqat va suv', 'Ozuqa, tirikchilik manbai', 'Sustenance (русский перевод)', 'The researcher used the word sustenance to clarify the findings in the study.', 'Tegishli ozuqasiz inson ochlikdan nobud bo''ladi.', 'The researcher used the word ______ to clarify the findings in the study.', 'sustenance', '"nourishment","food","livelihood"'::TEXT[], '"basic sustenance","source of sustenance"'::TEXT[], 'B2', 19, TRUE),
  ('w20', 'Tedious', 'tedious', 1, 'adjective', '/ˈtiː.di.əs/', '/ˈtiː.di.əs/', 'When something is tedious, it is long, frustrating, and boring.', 'Juda uzoq vaqt oladigan, bir xil va zerikarli', 'Zerikarli, cho''zilgan', 'Tedious (русский перевод)', 'His job involved a lot of tedious typing, filing, and organizing.', 'Uning ishi ko''plab zerikarli yozishmalar va saralashni talab qilardi.', 'His job involved a lot of ______ typing, filing, and organizing.', 'tedious', '"boring","tiresome","dull"'::TEXT[], '"tedious job","tedious process"'::TEXT[], 'B2', 20, TRUE),
  ('w21', 'Abbey', 'abbey', 2, 'noun', '/ˈæb.i/', '/ˈæb.i/', 'To abbey means to perform or exhibit abbey in a given academic or social context.', 'Rohiblar yoki rohibalar yashaydigan maskan', 'Monastir, abbatlik', 'Abbey (русский перевод)', 'When the monk returned to the abbey, he went immediately to his bedroom.', 'Rohib monastirga qaytgach, darhol o''z xonasiga kirdi.', 'When the monk returned to the ______, he went immediately to his bedroom.', 'abbey', '"monastery","convent"'::TEXT[], '"ancient abbey","visit an abbey"'::TEXT[], 'B2', 21, TRUE),
  ('w22', 'Abundant', 'abundant', 2, 'adjective', '/əˈbʌn.dənt/', '/əˈbʌn.dənt/', 'If something is abundant, then it is available in large quantities.', 'Katta miqdorda mavjud bo''lgan', 'Mo''l-ko''l, serob', 'Abundant (русский перевод)', 'Cakes, cookies, and candy were so abundant that the child was very happy.', 'Pishiriqlar va shirinliklar shu qadar ko''p ediki, bola juda quvondi.', 'Cakes, cookies, and candy were so ______ that the child was very happy.', 'abundant', '"plentiful","bountiful","ample"'::TEXT[], '"abundant supply","abundant resources"'::TEXT[], 'B2', 22, TRUE),
  ('w23', 'Adjoin', 'adjoin', 2, 'verb', '/əˈdʒɔɪn/', '/əˈdʒɔɪn/', 'To adjoin means to perform or exhibit adjoin in a given academic or social context.', 'Biror narsaga yopishgan yoki unga bevosita qo''shni bo''lmoq', 'Yondosh bo''lmoq, tutashmoq', 'Adjoin (русский перевод)', 'She can listen to her brother’s conversations because her room adjoins his.', 'Yangi ovqatlanish zali mehmonxonaga tutash qilib qurilgan.', 'She can listen to her brother’s conversations because her room ______s his.', 'adjoin', '"border","neighbor","abut"'::TEXT[], '"adjoining room","adjoin the park"'::TEXT[], 'B2', 23, TRUE),
  ('w24', 'Ample', 'ample', 2, 'adjective', '/ˈæm.pəl/', '/ˈæm.pəl/', 'To ample means to perform or exhibit ample in a given academic or social context.', 'Talab qilinganidan ko''proq bo''lgan, yetarli', 'Yetarli darajada ko''p, keng', 'Ample (русский перевод)', 'The researcher used the word ample to clarify the findings in the study.', 'Bizda loyihani tugatish uchun yetarli vaqt bor edi.', 'The researcher used the word ______ to clarify the findings in the study.', 'ample', '"sufficient","plenty","copious"'::TEXT[], '"ample opportunity","ample evidence"'::TEXT[], 'B2', 24, TRUE),
  ('w25', 'Arid', 'arid', 2, 'adjective', '/ˈær.ɪd/', '/ˈær.ɪd/', 'If a place is arid, then it is hot and dry and gets very little or no rain.', 'Yog''ingarchilik juda kam bo''ladigan issiq va quruq yer', 'Qurg''oqchil, quruq', 'Arid (русский перевод)', 'Not many plants grow in the arid desert.', 'Qurg''oqchil cho''lda ko''p o''simliklar o''smaydi.', 'Not many plants grow in the ______ desert.', 'arid', '"dry","parched","barren"'::TEXT[], '"arid climate","arid zone"'::TEXT[], 'B2', 25, TRUE),
  ('w26', 'Cathedral', 'cathedral', 2, 'noun', '/kəˈθiː.drəl/', '/kəˈθiː.drəl/', 'To cathedral means to perform or exhibit cathedral in a given academic or social context.', 'Yirik va muhim diniy bino', 'Bosh cherkov, sobor', 'Cathedral (русский перевод)', 'The large cathedral is full of people on Sunday mornings.', 'Shahar markazidagi sobor ulkan va go''zal me''morchilikka ega.', 'The large ______ is full of people on Sunday mornings.', 'cathedral', '"church","basilica"'::TEXT[], '"gothic cathedral","ancient cathedral"'::TEXT[], 'B2', 26, TRUE),
  ('w27', 'Deprive', 'deprive', 2, 'verb', '/dɪˈpraɪv/', '/dɪˈpraɪv/', 'To deprive means to perform or exhibit deprive in a given academic or social context.', 'Kimgadir kerakli narsani olishiga yo''l qo''ymaslik', 'Mahrum qilmoq', 'Deprive (русский перевод)', '» Because the child was bad, she was deprived of her dessert after dinner.', 'Uyqusizlik odamning aqliy diqqatini pasaytiradi.', '» Because the child was bad, she was ______d of her dessert after dinner.', 'deprive', '"strip","rob","deny"'::TEXT[], '"deprive of sleep","deprived child"'::TEXT[], 'B2', 27, TRUE),
  ('w28', 'Drought', 'drought', 2, 'noun', '/draʊt/', '/draʊt/', 'To drought means to perform or exhibit drought in a given academic or social context.', 'Uzoq vaqt yomg''ir yog''maslik davri', 'Qurg''oqchilik', 'Drought (русский перевод)', 'After three months of drought, the vegetation and trees started dying.', 'Kuchli qurg''oqchilik dehqonlarning hosilini nobud qildi.', 'After three months of ______, the vegetation and trees started dying.', 'drought', '"dry spell","parchedness"'::TEXT[], '"severe drought","suffer from drought"'::TEXT[], 'B2', 28, TRUE),
  ('w29', 'Eligible', 'eligible', 2, 'adjective', '/ˈel.ɪ.dʒə.bəl/', '/ˈel.ɪ.dʒə.bəl/', 'If someone is eligible, then they are permitted to do or have something.', 'Talablarga to''liq javob beradigan', 'Munosib, huquqiga ega', 'Eligible (русский перевод)', 'Only people who bought tickets were eligible to win a prize.', 'Faqat yuqori baho olgan talabalar grantga munosib hisoblanadi.', 'Only people who bought tickets were ______ to win a prize.', 'eligible', '"qualified","suitable","entitled"'::TEXT[], '"eligible for scholarship","eligible candidate"'::TEXT[], 'B2', 29, TRUE),
  ('w30', 'Fast', 'fast', 2, 'verb', '/fɑːst/', '/fɑːst/', 'To fast means to perform or exhibit fast in a given academic or social context.', 'Muayyan vaqt davomida ovqat yemay yurmoq', 'Ro''za tutmoq, ovqatdan tiyilmoq', 'Fast (русский перевод)', 'In her religion, they fast for five days and then have a big feast.', 'Tibbiy ko''rikdan oldin bemor 12 soat ovqat yemadi.', 'In her religion, they ______ for five days and then have a big feast.', 'fast', '"abstain","diet"'::TEXT[], '"fast for medical test","religious fast"'::TEXT[], 'B2', 30, TRUE),
  ('w31', 'Grumble', 'grumble', 2, 'verb', '/ˈɡrʌm.bəl/', '/ˈɡrʌm.bəl/', 'To grumble means to perform or exhibit grumble in a given academic or social context.', 'Past ovozda shikoyat qilmoq', 'G''o''ldiramoq, norozi ohangda gapirmoq', 'Grumble (русский перевод)', 'He grumbled about having to work late on Friday.', 'Ishchilar past ish haqi haqida g''o''ldirashdi.', 'He ______d about having to work late on Friday.', 'grumble', '"mutter","whine","complain"'::TEXT[], '"grumble about","grumble under one''s breath"'::TEXT[], 'B2', 31, TRUE),
  ('w32', 'Inland', 'inland', 2, 'adverb', '/ˌɪn.lænd/', '/ˌɪn.lænd/', 'If someone goes inland, they travel into the center of a country or land.', 'Dengiz qirg''og''idan uzoqdagi ichki qism', 'Ichki hudud, quruqlik ichkarisi', 'Inland (русский перевод)', 'The river curved inland near the campground.', 'Bo''rondan saqlanish uchun ular mamlakat ichkarisiga qarab ketishdi.', 'The river curved ______ near the campground.', 'inland', '"interior","upcountry"'::TEXT[], '"travel inland","inland lake"'::TEXT[], 'B2', 32, TRUE),
  ('w33', 'Moisture', 'moisture', 2, 'noun', '/ˈmɔɪs.tʃər/', '/ˈmɔɪs.tʃər/', 'To moisture means to perform or exhibit moisture in a given academic or social context.', 'Havoda yoki sirtda joylashgan suv tomchilari', 'Namlik, rutubat', 'Moisture (русский перевод)', 'If you breathe on a window, moisture from your breath collects on the glass.', 'Tuproqdagi namlik o''simliklarning tez o''sishiga yordam beradi.', 'If you breathe on a window, ______ from your breath collects on the glass.', 'moisture', '"humidity","dampness","wetness"'::TEXT[], '"retain moisture","soil moisture"'::TEXT[], 'B2', 33, TRUE),
  ('w34', 'Nonetheless', 'nonetheless', 2, 'adverb', '/ˌnʌn.ðəˈles/', '/ˌnʌn.ðəˈles/', 'If something happens nonetheless, then it occurs despite some other thing.', 'Aytilgan faktga qaramasdan', 'Shunga qaramay', 'Nonetheless (русский перевод)', 'She tried to keep the dog out of the mud, but it got dirty nonetheless.', 'Yomg''ir yog''ayotgan edi, shunga qaramay biz piyoda sayrga chiqdik.', 'She tried to keep the dog out of the mud, but it got dirty ______.', 'nonetheless', '"nevertheless","however","still"'::TEXT[], '"hard, nonetheless rewarding","nonetheless important"'::TEXT[], 'B2', 34, TRUE),
  ('w35', 'Oath', 'oath', 2, 'noun', '/əʊθ/', '/əʊθ/', 'An oath is a formal, often public, promise.', 'Tantanali ravishda berilgan va''da', 'Qasamyod, ont', 'Oath (русский перевод)', 'Judges must take an oath to be fair to everyone in court.', 'Yangi prezident qasamyod qabul qildi.', 'Judges must take an ______ to be fair to everyone in court.', 'oath', '"pledge","vow","promise"'::TEXT[], '"take an oath","break an oath"'::TEXT[], 'B2', 35, TRUE),
  ('w36', 'Prairie', 'prairie', 2, 'noun', '/ˈpreə.ri/', '/ˈpreə.ri/', 'To prairie means to perform or exhibit prairie in a given academic or social context.', 'Daraxtsiz, keng maysazor tekislik', 'Dasht, preriy', 'Prairie (русский перевод)', 'The prairie was perfect for a farm because there were hills and trees.', 'Keng dasht fermerlik va chorvachilik uchun juda mos edi.', 'The ______ was perfect for a farm because there were hills and trees.', 'prairie', '"grassland","steppe","plain"'::TEXT[], '"open prairie","prairie landscape"'::TEXT[], 'B2', 36, TRUE),
