  ('w40', 'Speculate', 'speculate', 2, 'verb', '/ˈspek.jə.leɪt/', '/ˈspek.jə.leɪt/', 'To speculate means to perform or exhibit speculate in a given academic or social context.', 'Aniq bilmasdan turib fikr bildirmoq', 'Taxmin qilmoq', 'Speculate (русский перевод)', 'My sister looked at the sky and speculated that it would rain tomorrow.', 'Olimlar bu kashfiyot kelajakka qanday ta''sir qilishini taxmin qilishdi.', 'My sister looked at the sky and ______d that it would rain tomorrow.', 'speculate', '"guess","theorize","conjecture"'::TEXT[], '"speculate on","wildly speculate"'::TEXT[], 'B2', 40, TRUE),
  ('w41', 'Analytic', 'analytic', 3, 'verb', '/analytic/', '/analytic/', 'If something is analytic, it is related to logic and reasoning.', 'Analytic so''zining ingliz tilidagi rasmiy ta''rifi: If something is analytic, it is related to logic and reasoning.', 'Analytic (o''zbekcha ma''nosi)', 'Analytic (русский перевод)', 'The analytic article criticized the new plan and presented one of its own.', 'Namuna gapning o''zbekcha tarjimasi: The analytic article criticized the new plan and presented one of its own.', 'The ______ article criticized the new plan and presented one of its own.', 'analytic', '"analytic","synonym"'::TEXT[], '"use analytic","academic analytic"'::TEXT[], 'B2', 41, TRUE),
